"""Netrunning: decks, programs, Demons, Net rolls, writing programs, fortresses, and a live run at the table."""
import asyncio, json, sys, os, re
from playwright.async_api import async_playwright
from harness import *

SHOTS=os.path.join(OUT,"net");os.makedirs(SHOTS,exist_ok=True)
def shot(n):return os.path.join(SHOTS,n)
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch()
        pl=await page(b,"P","player.html");pl.set_default_timeout(8000)
        await make_runner(pl,"Spider")
        await pl.click(".card:has-text('Spider') >> text=Open sheet");await pl.wait_for_timeout(300)
        ok(await pl.locator("[data-act=tab][data-t=net]").count()==0,"a Solo with no deck has no Netrunning tab")
        await pl.evaluate("""()=>{const c=curChar();c.role='Netrunner';c.stats.INT=8;c.stats.REF=8;c.skills['Interface']={c:6,p:0,b:0};c.skills['Programming']={c:5,p:0,b:0};c.eb=60000;c.cyber=c.cyber.filter(x=>!/plug/i.test(x.name));saveChar(c,true);render()}""")
        await pl.click("[data-act=tab][data-t=net]");await pl.wait_for_timeout(200)
        ok("No deck yet" in await pl.inner_text("main"),"the Netrunning tab shows up for a netrunner and asks for a deck")
        # buy a deck
        await pl.click("text=Buy a cyberdeck");await pl.wait_for_timeout(200)
        ok(await pl.evaluate("ui.modal")=="shop" and await pl.evaluate("ui.shopTab")=="Decks","Buy a cyberdeck opens the shop on Decks")
        i=await pl.evaluate("DECKS.findIndex(r=>r[0]==='Zetatech Parraline 5750')")
        await pl.hover(f".shop-row[data-info='d:{i}'] .t");await pl.wait_for_timeout(150)
        dt=await pl.inner_text("#shop-detail");print("deck detail:",dt[:200])
        ok("speed" in dt.lower() and "upgrades" in dt.lower(),"pointing at a deck explains it")
        await pl.screenshot(path=shot("shop-decks.png"))
        await pl.click(f"[data-act=buy][data-k=d][data-i='{i}']");await pl.wait_for_timeout(150)
        dk=await pl.evaluate("curChar().deck")
        ok(dk and dk["name"]=="Zetatech Parraline 5750" and dk["speed"]==2 and dk["wall"]==4 and dk["mu"]==10,"bought the Parraline 5750 with the book's stats (Speed +2, walls 4, 10 MU)")
        ok(await pl.evaluate("curChar().eb")==60000-3600,"paid 3,600eb")
        ok(dk["conn"]=="keyboard","with no interface plugs, the keyboard it comes with is used")
        # programs
        await pl.click("[data-act=shop-tab][data-t=Programs]");await pl.wait_for_timeout(150)
        idx=await pl.evaluate("Object.fromEntries(['Hammer','Codecracker','Killer IV','Imp','Invisibility','Force Shield','Hellbolt','Crystal Ball'].map(n=>[n,SHOP_LISTS.p().findIndex(r=>r[0]===n)]))")
        await pl.hover(f".shop-row[data-info='p:{idx['Hellbolt']}'] .t");await pl.wait_for_timeout(150)
        t=await pl.inner_text("#shop-detail");ok("1D10" in t and "INT" in t and "Interface" in t,"pointing at Hellbolt shows its damage and the anti-personnel roll")
        for n in ["Hammer","Codecracker","Killer IV","Imp","Invisibility","Force Shield"]:
            await pl.click(f"[data-act=buy][data-k=p][data-i='{idx[n]}']");await pl.wait_for_timeout(80)
        await pl.screenshot(path=shot("shop-programs.png"))
        await pl.click("[data-act=close-modal]");await pl.wait_for_timeout(150)
        progs=await pl.evaluate("curChar().programs.map(p=>[p.name,p.str,p.mu,p.loaded])");print(progs)
        ok(len(progs)==6,"six programs bought")
        ok(await pl.evaluate("muUsed(curChar())")<=10,"programs that don't fit go on chips (%d MU loaded)"%await pl.evaluate("muUsed(curChar())"))
        ok(any(not x[3] for x in progs),"at least one went to a chip")
        # Demon: put Killer IV in the Imp
        kid=await pl.evaluate("curChar().programs.find(p=>p.name==='Killer IV').id");imp=await pl.evaluate("curChar().programs.find(p=>p.name==='Imp').id")
        await pl.evaluate(f"(()=>{{const c=curChar();c.programs.forEach(p=>p.loaded=false);c.programs.find(p=>p.id==='{imp}').loaded=true;saveChar(c);render()}})()");await pl.wait_for_timeout(100)
        await pl.select_option(f"select[data-act-change=net-prog-in][data-id='{kid}']",imp);await pl.wait_for_timeout(150)
        ok(await pl.evaluate(f"curChar().programs.find(p=>p.id==='{kid}').in")==imp,"Killer IV goes into the Imp")
        ok(await pl.evaluate(f"progMU(curChar(),curChar().programs.find(p=>p.id==='{kid}'))")==3,"a Demon subroutine takes half its memory (5 → 3 MU)")
        ok(await pl.evaluate(f"progEffStr(curChar(),curChar().programs.find(p=>p.id==='{kid}'))")==3,"and fights at the Imp's Strength (3)")
        ok(await pl.evaluate("muUsed(curChar())")==6,"loaded memory counts the Imp and its packed Killer (3 + 3)")
        await pl.evaluate("(()=>{const c=curChar();c.programs.forEach(p=>{if(!p.in)p.loaded=['Hammer','Codecracker','Imp','Invisibility'].includes(p.name)||p.loaded});saveChar(c);render()})()")
        # upgrades
        eb=await pl.evaluate("curChar().eb");await pl.click("[data-act=net-up][data-k=speed]");await pl.wait_for_timeout(100)
        ok(await pl.evaluate("curChar().deck.speed")==3 and await pl.evaluate("curChar().eb")==eb-2000,"+1 Speed costs 2,000eb")
        await pl.click("[data-act=net-up][data-k=mu]");await pl.wait_for_timeout(100)
        ok(await pl.evaluate("curChar().deck.mu")==20,"a second memory takes the deck to 20 MU")
        ok(await pl.is_disabled("[data-act=net-up][data-k=mu]"),"and that's the limit")
        await pl.evaluate("(()=>{const c=curChar();c.deck.speed=5;saveChar(c);render()})()");ok(await pl.is_disabled("[data-act=net-up][data-k=speed]"),"Speed stops at +5")
        await pl.evaluate("(()=>{const c=curChar();c.deck.speed=3;saveChar(c);render()})()")
        # connection and initiative
        await pl.click("[data-act=net-conn][data-v=trodes]");await pl.wait_for_timeout(100)
        ini=await pl.evaluate("netInitParts(curChar())");ok(ini["base"]==await pl.evaluate("calc(curChar()).eff.REF")-2+3,"Net initiative = REF − 2 ('trodes) + Speed 3 (%s)"%ini["parts"])
        await pl.evaluate("window.__nd=nd10;nd10=()=>7;0")
        await pl.click("[data-act=net-init]");await pl.wait_for_timeout(100)
        e=await pl.evaluate("Dice.log[0]");ok(e["label"]=="Net initiative" and e["total"]==ini["base"]+7,"Net initiative rolls REF + Speed + mods + 1D10")
        await pl.screenshot(path=shot("tab-net.png"),full_page=True)
        # Net roll window
        hid=await pl.evaluate("curChar().programs.find(p=>p.name==='Hammer').id")
        await pl.click(f"[data-act=net-roll-open][data-id='{hid}']");await pl.wait_for_timeout(150)
        ok(await pl.evaluate("ui.modal")=="netroll","Run opens the Net roll window")
        await pl.fill("#nr-t","5")
        await pl.evaluate("window.__seq=[8,3];window.__calls=[];nd10=()=>{window.__calls.push(new Error().stack.split('\\n')[2]);return window.__seq.shift()||1};0")
        await pl.click("[data-act=nr-roll]");await pl.wait_for_timeout(100)
        e=await pl.evaluate("Dice.log[0]");print(e["detail"],await pl.evaluate("window.__calls"))
        ok(e["total"]==12 and "vs 5 + D10 (3) = 8" in e["detail"] and e["tags"][0]["t"]=="Succeeds","Hammer: STR 4 + 8 = 12 beats wall 5 + 3 = 8")
        ok("wall loses" in e["detail"],"and rolls 2D6 off the wall")
        ok("alerted" in (await pl.inner_text(".ck-res")).lower(),"Hammer always alerts the system")
        await pl.screenshot(path=shot("netroll.png"))
        await pl.evaluate("window.__seq=[1,9]")
        await pl.click("[data-act=nr-roll]");await pl.wait_for_timeout(100)
        ok(await pl.evaluate("Dice.log[0].tags[0].t")=="Fails","a lower total fails")
        # anti-personnel defence: Force Shield
        fs=await pl.evaluate("curChar().programs.find(p=>p.name==='Force Shield').id")
        await pl.select_option("#nr-p",fs);await pl.wait_for_timeout(100)
        base=await pl.evaluate("4+calc(curChar()).eff.INT+skillLevel(curChar(),'Interface')")
        ok(("= %d + 1D10"%base) in await pl.inner_text(".ck-roll"),"Force Shield defends with STR + INT + Interface (%d)"%base)
        # controller
        await pl.click("[data-act=close-modal]")
        await pl.evaluate("(()=>{const c=curChar();c.programs.push(mkProgram(progRow('Crystal Ball')));saveChar(c);render()})()")
        cb=await pl.evaluate("curChar().programs.find(p=>p.name==='Crystal Ball').id")
        await pl.click(f"[data-act=net-roll-open][data-id='{cb}']");await pl.evaluate("nd10=()=>4;0");await pl.click("[data-act=nr-roll]");await pl.wait_for_timeout(100)
        ok(await pl.evaluate("Dice.log[0].tags[0].t")=="Works","a controller works on 1D10 ≤ its Strength (4 ≤ 4)")
        await pl.click("[data-act=close-modal]")
        # writing a program: the book's Hellhound example
        await pl.click("[data-act=net-write-open]");await pl.wait_for_timeout(150)
        for v in ["Anti-Personnel"]:await pl.check(f"input[data-k=funcs][value='{v}']");await pl.wait_for_timeout(60)
        for v in ["Movement ability","Trace","Recognition","ICON (superrealistic)"]:await pl.check(f"input[data-k=opts][value='{v}']");await pl.wait_for_timeout(60)
        await pl.fill("#nw-str","6");await pl.wait_for_timeout(150)
        r=await pl.evaluate("nwCalc(ui.nw)");print(r)
        ok(r["diff"]==40 and r["mu"]==6 and r["cost"]==10000,"Hellhound by the book: Difficulty 40, 6 MU, 10,000eb")
        ok(r["hours"]==240,"240 hours of work")
        await pl.fill("#nw-name","Hellhound");await pl.evaluate("d10x=()=>[10,10,10,10,9];0")
        await pl.click("[data-act=nw-roll]");await pl.wait_for_timeout(150)
        ok(await pl.evaluate("ui.nw.last.ok"),"INT + Programming + 1D10 beats the Difficulty")
        await pl.screenshot(path=shot("write.png"))
        await pl.click("[data-act=nw-add]");await pl.wait_for_timeout(150)
        hh=await pl.evaluate("curChar().programs.find(p=>p.name==='Hellhound')")
        ok(hh and hh["cls"]=="Anti-Personnel" and hh["str"]==6 and hh["mu"]==6 and not hh["loaded"],"the written program is added on a chip")
        # paper sheet
        html=await pl.evaluate("sheetPages(curChar(),{})");ok("Cyberdeck" in html and "Killer IV" in html and "Imp › Killer IV" in html,"the paper sheet gets a cyberdeck & programs page")
        ok("Cyberdeck" not in await pl.evaluate("sheetPages(SAMPLE,{})"),"runners without a deck don't")
        # the sample runner is still the same
        await pl.evaluate("nd10=window.__nd")

        # ---------------- GM ----------------
        gm=await page(b,"GM","gm.html");gm.set_default_timeout(8000)
        await gm.click("nav [data-act=tab][data-t=net]");await gm.wait_for_timeout(200)
        ok("Data fortresses" in await gm.inner_text("main"),"GM has a Netrunning tab")
        await gm.click("[data-act=nf-sample]");await gm.wait_for_timeout(200)
        s=await gm.evaluate("fortStats(netFortSel())");print(s["cost"])
        ok(s["cpus"]==2 and s["INT"]==6 and s["wallStr"]==4 and s["actions"]==1 and not s["ai"],"sample: 2 CPUs, INT 6, walls 4, one action")
        ok(s["warn"]==[],"the sample has no warnings %s"%s["warn"])
        ok(s["cost"][0][1]==20000 and any("Data walls" in c[0] and c[1]==2000 for c in s["cost"]),"costs: 10,000eb a CPU, 1,000eb per wall level")
        await gm.screenshot(path=shot("gm-sample.png"),full_page=True)
        # fast fortress
        await gm.evaluate("window.__r=d")
        for _ in range(5):
            f=await gm.evaluate("(()=>{const f=fastFortress('T');return {s:fortStats(f),n:f.progs.length,gates:Object.values(f.cells).filter(c=>c.t==='gate').map(c=>c.str)}})()")
            cp=f["s"]["cpus"];ok(1<=cp<=6 and f["s"]["mems"]==cp*4 and f["s"]["gates"]==cp and cp+1<=f["n"]<=cp+6 and cp<=f["s"]["wallStr"]<=cp+3 and all(cp<=g<=cp+3 for g in f["gates"]) and not f["s"]["warn"],"fast fortress (%d CPU): 4 memories and a gate per CPU, 1D6+CPU defences, walls 1D6/2+CPU, no warnings %s"%(cp,f["s"]["warn"]))
        await gm.click("[data-act=nf-fast]");await gm.wait_for_timeout(200)
        ok("Data walls Strength" in await gm.evaluate("netFortSel().notes"),"the rolls are written into the fortress's notes")
        # editing
        await gm.click("[data-act=nf-new]");await gm.wait_for_timeout(150)
        await gm.click("[data-act=nf-tool][data-v=cpu]");await gm.click("[data-act=nf-cell][data-x='5'][data-y='5']")
        await gm.click("[data-act=nf-tool][data-v=mem]");await gm.click("[data-act=nf-cell][data-x='6'][data-y='5']")
        await gm.click("[data-act=nf-tool][data-v=wall]")
        c1=await gm.locator("[data-act=nf-cell][data-x='3'][data-y='3']").bounding_box();c2=await gm.locator("[data-act=nf-cell][data-x='8'][data-y='3']").bounding_box()
        await gm.mouse.move(c1["x"]+5,c1["y"]+5);await gm.mouse.down();await gm.mouse.move(c2["x"]+5,c2["y"]+5,steps=12);await gm.mouse.up();await gm.wait_for_timeout(200)
        n=await gm.evaluate("Object.values(netFortSel().cells).filter(c=>c.t==='wall').length");ok(n==6,"dragging draws a line of data walls (%d)"%n)
        await gm.click("[data-act=nf-tool][data-v=gate]");await gm.click("[data-act=nf-cell][data-x='5'][data-y='3']")
        ok(await gm.evaluate("netFortSel().cells['5,3'].t")=="gate" and await gm.evaluate("netFortSel().cells['5,3'].str")==2,"a code gate starts at Strength 2")
        await gm.click("[data-act=nf-tool][data-v=prog]");await gm.select_option("select[data-act-change=nf-prog]","Hellhound");await gm.click("[data-act=nf-cell][data-x='6'][data-y='5']")
        ok(await gm.evaluate("netFortSel().progs.some(p=>p.name==='Hellhound'&&p.x===6&&p.y===5)"),"a Hellhound placed in the memory")
        ok(any("Hellhound" in c[0] or c[1]==10000 for c in await gm.evaluate("fortStats(netFortSel()).cost")),"its 10,000eb is in the cost")
        await gm.click("[data-act=nf-tool][data-v=select]");await gm.click("[data-act=nf-cell][data-x='6'][data-y='5']");await gm.wait_for_timeout(100)
        await gm.click("[data-act=nf-file-add]");await gm.wait_for_timeout(100)
        await gm.fill("input[data-nc='files.0.name']","Secret plans");await gm.wait_for_timeout(100)
        ok(await gm.evaluate("netFortSel().cells['6,5'].files[0].name")=="Secret plans","files are edited in the memory")
        # sanFort round trip (campaign packages)
        rt=await gm.evaluate("(()=>{const f=sanFort(JSON.parse(JSON.stringify(netFortSel())));return [Object.keys(f.cells).length,f.progs.length,f.cells['6,5'].files[0].name]})()")
        ok(rt==[await gm.evaluate("Object.keys(netFortSel().cells).length"),1,"Secret plans"],"a fortress survives being read back from a package")
        evil=await gm.evaluate("(()=>{const f=sanFort({name:'<b>x</b>',cells:{'99,1':{t:'wall'},'1,1':{t:'nope'},'2,2':{t:'gate',str:99}},progs:[{name:'X',cls:'Bad',str:50,x:-4}]});return [f.name,Object.keys(f.cells),f.cells['2,2'].str,f.progs[0].cls,f.progs[0].str,f.progs[0].x]})()")
        ok(evil==["b x /b",["2,2"],10,"Utility",10,0],"bad fortress data is cleaned up %s"%evil)

        # ---------------- the run ----------------
        await gm.click("[data-act=nf-sel] >> text=Kestrel");await gm.wait_for_timeout(150)
        await gm.click("[data-act=open-modal][data-m=host] >> nth=0");await gm.wait_for_timeout(150)
        await gm.click("[data-act=host-online]");await gm.wait_for_timeout(900)
        await gm.click("[data-act=copy-invite] >> nth=-1");await gm.wait_for_timeout(100);code=await gm.evaluate("window.__clip");await gm.click("[data-act=close-modal]")
        await pl.evaluate("(()=>{const c=curChar();c.deck.conn='trodes';c.programs.forEach(p=>{if(!p.in)p.loaded=['Hammer','Codecracker','Imp','Invisibility','Force Shield','Crystal Ball'].includes(p.name)});saveChar(c,true)})()")
        await pl.click("nav [data-act=go-roster]");await pl.wait_for_timeout(100)
        await join(pl,code,"Ana","Spider");await pl.wait_for_timeout(500)
        ok(await gm.evaluate("st.party.some(c=>c.handle==='Spider'&&c.deck)"),"Spider joins with her deck")
        await gm.click("nav [data-act=tab][data-t=net]");await gm.wait_for_timeout(150)
        await gm.click("[data-act=nf-run]");await gm.wait_for_timeout(150)
        ok(await gm.is_checked(".ns-who"),"runners with decks are ticked")
        await gm.click("[data-act=nr-start]");await gm.wait_for_timeout(800)
        run=await gm.evaluate("(()=>{const r=netRun();const sp=Object.values(r.runners)[0];return {x:sp.x,y:sp.y,progs:sp.progs.map(p=>p.name),seen:sp.seen.length}})()");print(run)
        ok(run["x"]==15 and run["y"]==12,"Spider starts at the way in (P13)")
        ok("Killer IV" in run["progs"] and "Imp" in run["progs"],"her loaded programs come along, Demon subroutines too")
        ok(await pl.evaluate("!!ui.netRun")and await pl.evaluate("ui.modal")=="net","the player's Net window opens when the GM starts the run")
        v=await pl.evaluate("ui.netRun")
        ok(not any(c["t"]=="mem" for c in v["cells"]),"from outside, she can't see the memories behind the walls")
        ok(not any(i["name"]=="Stun" for i in v["ice"]),"the hidden Stun isn't sent to her")
        await pl.screenshot(path=shot("player-net-1.png"))
        await gm.screenshot(path=shot("gm-run-1.png"),full_page=True)
        # moving too far is refused
        await pl.click("[data-act=pn-cell][data-x='19'][data-y='19']");await pl.wait_for_timeout(400)
        ok(await gm.evaluate("Object.values(netRun().runners)[0].x")==15 and "5 spaces" in await pl.inner_text("#toast-host"),"a move of more than 5 spaces is refused, with a reason")
        # Codecracker on the front gate (O13 = 14,12)
        cc=await pl.evaluate("ui.netRun.me.progs.find(p=>p.name==='Codecracker').id")
        await gm.evaluate("window.__seq=[9,1];nd10=()=>window.__seq.length?window.__seq.shift():5;0")
        await pl.click(f"[data-act=pn-prog][data-id='{cc}']");await pl.click("[data-act=pn-cell][data-x='14'][data-y='12']");await pl.wait_for_timeout(500)
        ok(await gm.evaluate("!!netRun().open['14,12']"),"Codecracker 3 + 9 beats the gate's 4 + 1: it opens")
        ok(any(c.get("open") for c in await pl.evaluate("ui.netRun.cells") if c["k"]=="14,12"),"the player sees the gate open")
        # a second action in the same round is refused
        await pl.click(f"[data-act=pn-prog][data-id='{cc}']");await pl.click("[data-act=pn-cell][data-x='10'][data-y='15']");await pl.wait_for_timeout(400)
        ok("already acted" in (await pl.inner_text("#toast-host")).lower(),"one action a round")
        # move in through the gate
        await pl.click("[data-act=pn-cell][data-x='13'][data-y='12']");await pl.wait_for_timeout(500)
        r0=await gm.evaluate("(()=>{const r=Object.values(netRun().runners)[0];return [r.x,r.y]})()");ok(r0==[13,12],"she moves inside through the open gate")
        v=await pl.evaluate("ui.netRun");ok(any(c["t"]=="mem" for c in v["cells"]),"inside, she sees the memories now")
        ok(any(i["name"]=="Watchdog" for i in v["ice"]),"and the Watchdog")
        await pl.screenshot(path=shot("player-net-2.png"))
        # next round, the Watchdog scans her; she's running Invisibility
        await gm.click("[data-act=nr-next]");await gm.wait_for_timeout(200)
        inv=await pl.evaluate("ui.netRun.me.progs.find(p=>p.name==='Invisibility').id")
        await pl.click(f"[data-act=pn-prog][data-id='{inv}']");await pl.wait_for_timeout(400)
        ok(await gm.evaluate("Object.values(netRun().runners)[0].active['Evasion/Stealth']")==inv,"running Invisibility keeps it up")
        wd=await gm.evaluate("netRun().ice.find(i=>i.name==='Watchdog').id")
        await gm.evaluate(f"ui.netISel='{wd}';render()");await gm.wait_for_timeout(100)
        await gm.evaluate("window.__seq=[2,9]");await gm.click("[data-act=ni-act]");await gm.wait_for_timeout(400)
        ok(not await gm.evaluate("Object.values(netRun().runners)[0].detected"),"Watchdog 4 + 2 doesn't beat Invisibility 3 + 9: she stays hidden")
        await gm.evaluate("window.__seq=[9,1]");await gm.click("[data-act=ni-act]");await gm.wait_for_timeout(400)
        ok(await gm.evaluate("Object.values(netRun().runners)[0].detected") and await gm.evaluate("netRun().ice.filter(i=>i.alive).every(i=>i.alerted)"),"a better roll spots her and alerts every defence")
        # Hellbolt hits her: wounds go up on the GM's copy and sync to the player
        await gm.click("[data-act=nr-next]");await gm.wait_for_timeout(150)
        hb=await gm.evaluate("netRun().ice.find(i=>i.name==='Hellbolt').id");await gm.evaluate(f"ui.netISel='{hb}';render()")
        w0=await gm.evaluate("st.party.find(c=>c.handle==='Spider').wounds||0")
        await gm.evaluate("window.__seq=[10,1];window.__rd=rollDice;rollDice=e=>({total:6,text:'6'});0")
        await gm.click("[data-act=ni-act]");await gm.wait_for_timeout(600);await gm.evaluate("rollDice=window.__rd")
        w1=await gm.evaluate("st.party.find(c=>c.handle==='Spider').wounds||0");ok(w1==w0+6,"Hellbolt beats her Force Shield-less defence: 6 wound damage (%d → %d)"%(w0,w1))
        await pl.wait_for_timeout(500);ok(await pl.evaluate("curChar()?curChar().wounds:[...S.chars.values()].find(c=>c.handle==='Spider').wounds")==w1,"the damage reaches the player's runner")
        last=await gm.evaluate("netRun().log.slice(-1)[0].text");print(last);ok("Hellbolt" in last and "damage" in last,"the log says what happened")
        # Force Shield up, then Stun is held off
        fsid=await pl.evaluate("ui.netRun.me.progs.find(p=>p.name==='Force Shield').id")
        await gm.click("[data-act=nr-next]");await gm.wait_for_timeout(150)
        await pl.click(f"[data-act=pn-prog][data-id='{fsid}']");await pl.wait_for_timeout(400)
        st_=await gm.evaluate("netRun().ice.find(i=>i.name==='Stun')");await gm.evaluate(f"(()=>{{const i=netRun().ice.find(i=>i.name==='Stun');i.x=13;i.y=13;i.revealed=true;ui.netISel=i.id;render()}})()")
        await gm.evaluate("window.__seq=[1,10]");await gm.click("[data-act=ni-act]");await gm.wait_for_timeout(400)
        ok(not await gm.evaluate("Object.values(netRun().runners)[0].status.some(s=>s.t==='Frozen')"),"Force Shield holds off Stun")
        # Killer attacks her Imp; the Imp de-rezzes and takes its Killer with it
        await gm.evaluate("(()=>{const i=netRun().ice.find(i=>i.name==='Killer IV');ui.netISel=i.id;render()})()")
        await gm.evaluate("window.__seq=[10,1];rollDice=e=>({total:6,text:'6'});0");await gm.click("[data-act=ni-act]");await gm.wait_for_timeout(400);await gm.evaluate("rollDice=window.__rd")
        sp=await gm.evaluate("Object.values(netRun().runners)[0].progs.filter(p=>p.derez).map(p=>p.name)");print(sp)
        ok("Imp" in sp and "Killer IV" in sp,"the system's Killer goes for the Demon first; the Imp de-rezzes with its subroutine")
        # defences move 5 spaces a turn too, unless the GM overrides
        wp=await gm.evaluate(f"(()=>{{const i=netRun().ice.find(i=>i.id==='{wd}');ui.netISel=i.id;ui.netFree=false;render();return [i.x,i.y,[...fortReach(netRun().fort,runState(netRun()),i.x,i.y,5).keys()].length]}})()");await gm.wait_for_timeout(100)
        far=await gm.evaluate(f"(()=>{{const run=netRun();const i=run.ice.find(i=>i.id==='{wd}');const R=fortReach(run.fort,runState(run),i.x,i.y,9);for(const [k,dd] of R)if(dd>5){{const [x,y]=k.split(',').map(Number);return [x,y]}}return null}})()")
        ok(await gm.locator(".ng .reach").count()>0,"selecting a defence lights up its 5-space reach")
        if far:
            await gm.click(f"[data-act=nr-cell][data-x='{far[0]}'][data-y='{far[1]}']");await gm.wait_for_timeout(150)
            ok(await gm.evaluate(f"(()=>{{const i=netRun().ice.find(i=>i.id==='{wd}');return [i.x,i.y]}})()")==wp[:2],"a defence can't move more than 5 spaces")
            await gm.evaluate("ui.netFree=true;render()");await gm.wait_for_timeout(100)
            await gm.click(f"[data-act=nr-cell][data-x='{far[0]}'][data-y='{far[1]}']");await gm.wait_for_timeout(150)
            ok(await gm.evaluate(f"(()=>{{const i=netRun().ice.find(i=>i.id==='{wd}');return [i.x,i.y]}})()")==far,"unless the GM overrides")
            await gm.evaluate(f"(()=>{{const i=netRun().ice.find(i=>i.id==='{wd}');i.x={wp[0]};i.y={wp[1]};ui.netFree=false;ui.netISel=null;netChanged()}})()")
        else: ok(False,"found a square more than 5 away")
        await gm.evaluate("(()=>{const c=netRun().fort.cells[fkey(11,12)];c.files[0].eb=2500})()")
        eb0=await gm.evaluate("st.party.find(c=>c.handle==='Spider').eb")
        # read a memory and copy a file
        await gm.click("[data-act=nr-next]");await gm.wait_for_timeout(150)
        await gm.evaluate("(()=>{const r=Object.values(netRun().runners)[0];r.x=11;r.y=11;netChanged()})()");await pl.wait_for_timeout(400)
        await pl.click("[data-act=pn-read]");await pl.click("[data-act=pn-cell][data-x='11'][data-y='12']");await pl.wait_for_timeout(500)
        rd=await pl.evaluate("ui.netRun.read");ok(len(rd)==1 and list(rd.values())[0]["files"][0]["name"]=="Security rota","reading memory 7 shows its files")
        await gm.click("[data-act=nr-next]");await gm.wait_for_timeout(150)
        await pl.click("[data-act=pn-copy] >> nth=0");await pl.wait_for_timeout(600)
        ok("Security rota" in await gm.evaluate("st.party.find(c=>c.handle==='Spider').notes"),"copying a file writes it into the runner's notes")
        ok(await gm.evaluate("st.party.find(c=>c.handle==='Spider').eb")==eb0+2500 and "2,500eb" in await gm.evaluate("netRun().log.map(l=>l.text).join(' ')"),"a file with money in it pays the runner who copies it")
        await pl.wait_for_timeout(400);ok("Security rota" in await pl.evaluate("[...S.chars.values()].find(c=>c.handle==='Spider').notes"),"which reach the player")
        await pl.screenshot(path=shot("player-net-3.png"))
        await gm.screenshot(path=shot("gm-run-2.png"),full_page=True)
        # Flatline gets through her deck's walls and goes off the next turn
        await gm.evaluate("(()=>{const i=netRun().ice.find(i=>i.name==='Flatline');i.x=11;i.y=10;ui.netISel=i.id;render()})()")
        await gm.evaluate("window.__seq=[10,1];0");await gm.click("[data-act=ni-act]");await gm.wait_for_timeout(300)
        sp=await gm.evaluate("(()=>{const r=Object.values(netRun().runners)[0];return [r.out,(r.pending||[]).length]})()")
        ok(sp==[False,1],"Flatline gets through her deck's data walls but waits for the next turn")
        await gm.click("[data-act=nr-next]");await gm.wait_for_timeout(300)
        sp=await gm.evaluate("(()=>{const r=Object.values(netRun().runners)[0];return [r.out,r.status.map(s=>s.t)]})()")
        ok(sp[0] and "Interface fried" in sp[1],"next turn it fries her interface chip and she drops out %s"%sp[1])
        await gm.evaluate("(()=>{ui.netRSel=Object.keys(netRun().runners)[0];render()})()");await gm.click("[data-act=nr-out]");await gm.wait_for_timeout(200)
        ok(not await gm.evaluate("Object.values(netRun().runners)[0].out"),"the GM can jack her back in")
        # log off
        await gm.click("[data-act=nr-next]");await gm.wait_for_timeout(150)
        await gm.evaluate("nd10=()=>3;0");await pl.click("[data-act=pn-logoff]");await pl.wait_for_timeout(500)
        ok(await gm.evaluate("Object.values(netRun().runners)[0].out"),"Log off: 3 ≤ 8, she's out")
        await gm.click("[data-act=nr-end]");await gm.click("[data-act=nr-end]");await gm.wait_for_timeout(600)
        ok(await gm.evaluate("netRun()") is None and await pl.evaluate("ui.netRun") is None,"ending the run closes it for everyone")
        # homebrew programs reach the player's shop
        await gm.click("nav [data-act=tab][data-t=homebrew]");await gm.wait_for_timeout(150)
        await gm.click("[data-act=hb-new]");await gm.wait_for_timeout(150)
        await gm.click("[data-act=hb-sec][data-v=programs]");await gm.click("[data-act=hb-add]");await gm.wait_for_timeout(150)
        await gm.fill("input[data-hbe=name]","Black Mamba");await gm.select_option("select[data-hbe=cls]","Anti-Personnel");await gm.wait_for_timeout(200)
        await gm.fill("input[data-hbe='fx.wound']","3D6");await gm.wait_for_timeout(100)
        await gm.screenshot(path=shot("gm-homebrew-program.png"),full_page=True)
        await gm.click("[data-act=hb-sec][data-v=decks]");await gm.click("[data-act=hb-add]");await gm.wait_for_timeout(150);await gm.fill("input[data-hbe=name]","Hosaka Spike");await gm.wait_for_timeout(100)
        await gm.check("input[data-act-change=hb-use]");await gm.evaluate("hbPersist()");await gm.wait_for_timeout(1200)
        has=await pl.evaluate("[PROGRAMS.some(r=>r[0]==='Black Mamba'),DECKS.some(r=>r[0]==='Hosaka Spike'),(PROGRAMS.find(r=>r[0]==='Black Mamba')||[])[5]]")
        ok(has[0] and has[1] and has[2].get("wound")=="3D6","the player's shop gets the homebrew program (with its effect) and deck")
        print("errors:",errs)
        ok(not errs,"no page errors")
        await b.close()
    finish()
asyncio.run(main())
